using AqtCoreFW.SharedKernel.Abstractions;
using AqtCoreFW.SharedKernel.Domain;

namespace AqtCoreFW.Identity.Domain.Entities;

/// <summary>
/// Canonical artifact being signed — server-derived, never caller-trusted. Drives strategy routing
/// together with the resolved provider capabilities.
/// </summary>
public enum SigningArtifactKind
{
    /// <summary>Detached/data signature over raw bytes (form field value). No PDF assembly.</summary>
    DetachedData = 0,
    /// <summary>PDF generated by a form template (trusted source) — PAdES embedded signature.</summary>
    FormPdf = 1,
    /// <summary>PDF uploaded by an end user (untrusted) — must pass sandbox parse before signing.</summary>
    UploadedPdf = 2,
}

/// <summary>
/// Which underlying provider state-machine record this request is backed by. <see cref="None"/> until a
/// strategy creates the concrete record (Phases 2/3/5); the two existing machines stay the source of truth.
/// </summary>
public enum SigningUnderlyingKind
{
    None = 0,
    /// <summary>VGCA USB doc-flow round-trip — <see cref="SigningDocFlowRecord"/>.</summary>
    DocFlow = 1,
    /// <summary>Viettel Mysign async-callback transaction — <see cref="SigningPendingTransaction"/>.</summary>
    PendingTransaction = 2,
}

/// <summary>
/// Projected lifecycle state surfaced to callers/FE. NOT stored on <see cref="SigningRequest"/> — computed at
/// read time from the underlying record (see <see cref="SigningRequestStatusProjector"/>) so it can never drift.
/// </summary>
public enum SigningRequestStatus
{
    Pending = 0,
    InProgress = 1,
    Completed = 2,
    Failed = 3,
    Expired = 4,
}

/// <summary>
/// Workflow-seam aggregate: one provider-agnostic signing request that every caller (BP step, form-PDF flow,
/// form field) issues. The orchestrator routes it by <c>(artifact kind × provider capabilities)</c> to a
/// strategy and links the concrete provider record underneath.
///
/// <para><b>No stored status column (read-time projection).</b> This aggregate holds only immutable identity
/// plus the link to its underlying record. <c>GetStatus</c> JOINs that record at read time and maps its state
/// → <see cref="SigningRequestStatus"/>. This kills the dual-write race a denormalised status would create:
/// the underlying machine (<see cref="SigningDocFlowRecord"/> / <see cref="SigningPendingTransaction"/>) stays
/// the single source of truth, and there is nothing to keep in sync. The one terminal state recorded here
/// directly is a <see cref="FailureReason"/> set when the request is rejected BEFORE any underlying record
/// exists (guard or routing failure) — there is no underlying state for that case to project from.</para>
///
/// <para>T2 entity: long Id (internal) + Guid <see cref="PublicId"/> (the value callers poll with). Schema
/// [identity] via IdentityDbContext default schema. Tenant-scoped (RLS + soft-delete via base config).</para>
/// </summary>
public sealed class SigningRequest : AuditableEntity, ITenantScoped, IPublicIdentified
{
    /// <inheritdoc/>
    public Guid PublicId { get; private set; }

    /// <inheritdoc/>
    public Guid TenantId { get; private set; }

    /// <summary>Server-derived artifact classification (never caller-trusted).</summary>
    public SigningArtifactKind ArtifactKind { get; private set; }

    /// <summary>Reference to the artifact: a Files storage key (PDF kinds) or a form submission id (data).</summary>
    public string ArtifactRef { get; private set; } = string.Empty;

    /// <summary>Configured provider key for the tenant (e.g. "usb-vgca", "remote-viettel-mysign").</summary>
    public string ProviderKey { get; private set; } = string.Empty;

    /// <summary>The signer this request is bound to — the cert==signer invariant is asserted against this id.</summary>
    public Guid AssignedSignerId { get; private set; }

    /// <summary>
    /// Position of this request in an ordered multi-signer chain (1-based, default 1). When a document
    /// requires sequential signatures, each signer issues a separate <see cref="SigningRequest"/> with
    /// an incrementing sequence number. Signer N+1 may not begin until signer N's record is Completed.
    /// </summary>
    public int SignerSequenceNumber { get; private set; } = 1;

    /// <summary>Optional placement/appearance hint (e.g. PDF coordinate JSON). Null for detached data.</summary>
    public string? Placement { get; private set; }

    /// <summary>Which underlying state-machine backs this request. <see cref="SigningUnderlyingKind.None"/> until linked.</summary>
    public SigningUnderlyingKind UnderlyingKind { get; private set; }

    /// <summary>
    /// Id of the underlying provider record (DocFlow record id or Mysign transaction id). Stored as string to
    /// hold either the long DocFlow id or the Viettel-assigned string transaction id. Null until linked.
    /// </summary>
    public string? UnderlyingRecordId { get; private set; }

    /// <summary>
    /// Terminal failure reason recorded only when the request was rejected before dispatch (guard/routing).
    /// Once an underlying record is linked, failure is projected from that record, not stored here.
    /// </summary>
    public string? FailureReason { get; private set; }

    /// <summary>
    /// For UploadedPdf artifact kind only: the PublicId of the FileRecord in the Files module that was
    /// staged for signing. Null for FormPdf and DetachedData kinds where no Files record is involved.
    /// Stored here so the Files module can query signing steps for a file without a column on FileRecord
    /// (the signing lifecycle owns the correlation, not the file-storage aggregate).
    /// </summary>
    public Guid? SourceFileId { get; private set; }

    /// <summary>EF Core: private parameterless constructor for materialisation.</summary>
    private SigningRequest() { }

    /// <summary>
    /// Factory — creates a request in the unlinked (projects to <see cref="SigningRequestStatus.Pending"/>) state.
    /// </summary>
    /// <param name="signerSequenceNumber">
    /// Position in an ordered multi-signer chain (1-based, default 1). Callers issuing a
    /// single-signer request omit this parameter; multi-signer orchestration supplies it
    /// explicitly so the prior-round Completed guard can locate the preceding record.
    /// </param>
    public static SigningRequest Create(
        IGuidGenerator guidGenerator,
        Guid tenantId,
        SigningArtifactKind artifactKind,
        string artifactRef,
        string providerKey,
        Guid assignedSignerId,
        Guid initiatedBy,
        string? placement = null,
        int signerSequenceNumber = 1,
        Guid? sourceFileId = null)
    {
        ArgumentNullException.ThrowIfNull(guidGenerator);
        if (tenantId == Guid.Empty)
            throw new ArgumentException("TenantId must not be empty.", nameof(tenantId));
        if (string.IsNullOrWhiteSpace(artifactRef))
            throw new ArgumentException("ArtifactRef must not be empty.", nameof(artifactRef));
        if (string.IsNullOrWhiteSpace(providerKey))
            throw new ArgumentException("ProviderKey must not be empty.", nameof(providerKey));
        if (assignedSignerId == Guid.Empty)
            throw new ArgumentException("AssignedSignerId must not be empty.", nameof(assignedSignerId));
        if (initiatedBy == Guid.Empty)
            throw new ArgumentException("InitiatedBy must not be empty.", nameof(initiatedBy));
        if (signerSequenceNumber < 1)
            throw new ArgumentException("SignerSequenceNumber must be >= 1.", nameof(signerSequenceNumber));

        var request = new SigningRequest
        {
            PublicId             = guidGenerator.NewIdMonotonic(),
            TenantId             = tenantId,
            ArtifactKind         = artifactKind,
            ArtifactRef          = artifactRef,
            ProviderKey          = providerKey,
            AssignedSignerId     = assignedSignerId,
            Placement            = placement,
            UnderlyingKind       = SigningUnderlyingKind.None,
            SignerSequenceNumber = signerSequenceNumber,
            // Only meaningful for UploadedPdf; null for FormPdf / DetachedData.
            SourceFileId         = artifactKind == SigningArtifactKind.UploadedPdf ? sourceFileId : null,
        };
        request.SetAuditCreate(initiatedBy);
        return request;
    }

    /// <summary>
    /// Links the concrete provider record created by a strategy (Phases 2/3/5). After this, status is projected
    /// from the underlying record. Idempotency/ordering is enforced: a request can be linked at most once and
    /// never after a creation failure.
    /// </summary>
    public void LinkUnderlying(SigningUnderlyingKind kind, string underlyingRecordId, Guid modifiedBy)
    {
        if (kind == SigningUnderlyingKind.None)
            throw new ArgumentException("Underlying kind must be a concrete record kind.", nameof(kind));
        if (string.IsNullOrWhiteSpace(underlyingRecordId))
            throw new ArgumentException("UnderlyingRecordId must not be empty.", nameof(underlyingRecordId));
        if (FailureReason is not null)
            throw new InvalidOperationException("Cannot link an underlying record to a creation-failed request.");
        if (UnderlyingKind != SigningUnderlyingKind.None)
            throw new InvalidOperationException(
                $"Request is already linked to a {UnderlyingKind} record.");

        UnderlyingKind     = kind;
        UnderlyingRecordId = underlyingRecordId;
        SetAuditUpdate(modifiedBy);
    }

    /// <summary>
    /// Records a terminal creation failure (guard rejected the signer binding, or no strategy matched the
    /// artifact×capability cell) — before any underlying record exists. Evidence is retained, never dropped.
    /// </summary>
    public void MarkCreationFailed(string reason, Guid modifiedBy)
    {
        if (UnderlyingKind != SigningUnderlyingKind.None)
            throw new InvalidOperationException(
                "Cannot mark a dispatched request as creation-failed; failure is projected from the underlying record.");

        FailureReason = string.IsNullOrWhiteSpace(reason) ? "Unknown creation failure" : reason;
        SetAuditUpdate(modifiedBy);
    }
}
